CREATE TABLE IF NOT EXISTS tabela_usuario (email TEXT NOT NULL, nome TEXT NOT NULL, telefone TEXT NOT NULL, cpf TEXT NOT NULL, dataNascimento TEXT NOT NULL, tipoPerfil TEXT NOT NULL, isSynced INTEGER NOT NULL, PRIMARY KEY(email));
CREATE TABLE IF NOT EXISTS tabela_produto (id INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, emailNegociante TEXT NOT NULL, nomeNegociante TEXT NOT NULL, nome TEXT NOT NULL, preco TEXT NOT NULL, descricao TEXT NOT NULL, fotoPathLocal TEXT, isSynced INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS tabela_veiculo (placa TEXT NOT NULL, emailEntregador TEXT NOT NULL, modelo TEXT NOT NULL, marca TEXT NOT NULL, ano TEXT NOT NULL, isSynced INTEGER NOT NULL, PRIMARY KEY(placa));
CREATE TABLE IF NOT EXISTS tabela_pedido (id INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, emailCliente TEXT NOT NULL, enderecoEntrega TEXT NOT NULL, resumoItens TEXT NOT NULL, valorTotal TEXT NOT NULL, statusEntrega TEXT NOT NULL, isSynced INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS tabela_avaliacao (id INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, nomeProduto TEXT NOT NULL, emailAutor TEXT NOT NULL, nota INTEGER NOT NULL, comentario TEXT NOT NULL, isSynced INTEGER NOT NULL);
